Parameters

viewof preset = Inputs.select(
  ["Random", "Correlated (similarity in rankings across faculty/students)", "Anti-correlated (non-similarity in rankings across family/students) ", "Identity (i ↔ i)"],
  {label: "Ranking preset", value: "Random"}
)







viewof correlation = Inputs.range(
  [0, 1],
  {label: "Preference agreement (ρ)", step: 0.05, value: 0.7}
)







viewof proposerSide = Inputs.radio(
  ["Students", "Faculty"],
  {label: "Proposing side", value: "Faculty"}
)







viewof regenClick = Inputs.button("Regenerate", {label: " "})







n = 10







// Seed re-rolls only when Regenerate is clicked. Preset / correlation
// changes reuse the same seed so results are deterministic per seed.
seed = {
  regenClick;
  return Math.floor(Math.random() * 1e9);
}







// Generate initial preferences from preset. Subscribes to preset,
// correlation, and seed so any change triggers a fresh regeneration.
// Returns {faculty: [[...students]], students: [[...faculty]]}
initialPrefs = {
  const lcg = d3.randomLcg(seed / 1e9);
  const r = {
    uniform: lcg,
    normal: d3.randomNormal.source(lcg)(0, 1)
  };
  const mode = preset;
  const rho = correlation;

  // Permutation helper
  const shuffle = (arr) =&gt; {
    const a = [...arr];
    for (let i = a.length - 1; i &gt; 0; i--) {
      const j = Math.floor(r.uniform() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  };
  const range = Array.from({length: n}, (_, i) =&gt; i);

  // Qualities: faculty assess students on a shared latent score; students also assess faculty.
  const studentQuality = Array.from({length: n}, () =&gt; r.normal());
  const facultyQuality = Array.from({length: n}, () =&gt; r.normal());

  const rankBy = (scores) =&gt; {
    return range
      .slice()
      .sort((a, b) =&gt; scores[b] - scores[a]); // highest score first
  };

  let faculty, students;
  if (mode === "Random") {
    faculty = Array.from({length: n}, () =&gt; shuffle(range));
    students = Array.from({length: n}, () =&gt; shuffle(range));
  } else if (mode === "Identity (i ↔ i)") {
    faculty = Array.from({length: n}, (_, f) =&gt; {
      const rest = range.filter((x) =&gt; x !== f);
      return [f, ...rest];
    });
    students = Array.from({length: n}, (_, s) =&gt; {
      const rest = range.filter((x) =&gt; x !== s);
      return [s, ...rest];
    });
  } else {
    // Correlated / anti-correlated: each faculty ranks students by
    // studentQuality + noise; lower ρ → more noise → more idiosyncrasy.
    const sign = mode.startsWith("Anti-correlated") ? -1 : 1;
    const noiseSd = Math.max(0.01, Math.sqrt(1 - rho * rho) / Math.max(rho, 0.01));
    faculty = Array.from({length: n}, () =&gt; {
      const scores = studentQuality.map((q) =&gt; sign * q + noiseSd * r.normal());
      return rankBy(scores);
    });
    students = Array.from({length: n}, () =&gt; {
      const scores = facultyQuality.map((q) =&gt; sign * q + noiseSd * r.normal());
      return rankBy(scores);
    });
  }
  return {faculty, students};
}







// Build the draggable preference editor. Takes an initial ordering,
// returns an element whose `.value` is the current (reactive) ordering.
function prefEditor(initial, selfPrefix, otherPrefix) {
  const container = htl.html`&lt;div class="pref-grid"&gt;&lt;/div&gt;`;
  const state = initial.map((row) =&gt; [...row]);

  const rankLabels = (list) =&gt; {
    [...list.children].forEach((li, i) =&gt; {
      const rankEl = li.querySelector(".rank");
      if (rankEl) rankEl.textContent = (i + 1) + ".";
    });
  };

  state.forEach((row, idx) =&gt; {
    const panel = htl.html`&lt;div class="pref-panel"&gt;
      &lt;div class="pref-header"&gt;${selfPrefix}${idx + 1}&lt;/div&gt;
      &lt;ol class="pref-list"&gt;&lt;/ol&gt;
    &lt;/div&gt;`;
    const list = panel.querySelector(".pref-list");
    row.forEach((otherIdx) =&gt; {
      const li = htl.html`&lt;li data-id="${otherIdx}"&gt;&lt;span class="rank"&gt;&lt;/span&gt;${otherPrefix}${otherIdx + 1}&lt;/li&gt;`;
      list.appendChild(li);
    });
    rankLabels(list);
    // eslint-disable-next-line no-undef
    new Sortable(list, {
      animation: 120,
      ghostClass: "sortable-ghost",
      chosenClass: "sortable-chosen",
      onEnd: () =&gt; {
        state[idx] = [...list.children].map((li) =&gt; +li.dataset.id);
        rankLabels(list);
        container.value = state.map((r) =&gt; [...r]);
        container.dispatchEvent(new Event("input", {bubbles: true}));
      }
    });
    container.appendChild(panel);
  });

  container.value = state.map((r) =&gt; [...r]);
  return container;
}







Faculty preferences over students
Each column gives the rank-order of students for a faculty member (top = most preferred). Drag to reorder.

viewof facultyPrefs = prefEditor(initialPrefs.faculty, "F", "S")








Student preferences over faculty
Each column gives the rank-order of faculty for a student (top = most preferred). Drag to reorder.

viewof studentPrefs = prefEditor(initialPrefs.students, "S", "F")

Resulting match

function galeShapley(proposerPrefs, receiverPrefs) {
  const n = proposerPrefs.length;
  const receiverRank = receiverPrefs.map((row) =&gt; {
    const rk = new Array(n);
    row.forEach((p, i) =&gt; (rk[p] = i));
    return rk;
  });
  const nextProposal = new Array(n).fill(0);
  const engagedTo = new Array(n).fill(-1); // receiver idx -&gt; proposer idx
  const free = Array.from({length: n}, (_, i) =&gt; i);
  while (free.length) {
    const p = free.shift();
    const r = proposerPrefs[p][nextProposal[p]++];
    const current = engagedTo[r];
    if (current === -1) {
      engagedTo[r] = p;
    } else if (receiverRank[r][p] &lt; receiverRank[r][current]) {
      engagedTo[r] = p;
      free.push(current);
    } else {
      free.push(p);
    }
  }
  return engagedTo;
}







matching = {
  const students = studentPrefs;
  const faculty = facultyPrefs;
  const studentsPropose = proposerSide === "Students";
  const proposerPrefs = studentsPropose ? students : faculty;
  const receiverPrefs = studentsPropose ? faculty : students;
  const engagedTo = galeShapley(proposerPrefs, receiverPrefs);

  // Normalize into faculty -&gt; student mapping regardless of proposer side.
  const facultyToStudent = new Array(n);
  if (studentsPropose) {
    // engagedTo is receiver(faculty) -&gt; proposer(student)
    for (let f = 0; f &lt; n; f++) facultyToStudent[f] = engagedTo[f];
  } else {
    // engagedTo is receiver(student) -&gt; proposer(faculty)
    for (let s = 0; s &lt; n; s++) facultyToStudent[engagedTo[s]] = s;
  }

  // Build pair records with each side's rank of its match.
  const facultyRankOf = faculty.map((row) =&gt; {
    const rk = new Array(n);
    row.forEach((s, i) =&gt; (rk[s] = i));
    return rk;
  });
  const studentRankOf = students.map((row) =&gt; {
    const rk = new Array(n);
    row.forEach((f, i) =&gt; (rk[f] = i));
    return rk;
  });
  const pairs = facultyToStudent.map((s, f) =&gt; ({
    faculty: f,
    student: s,
    facultyRankOfStudent: facultyRankOf[f][s] + 1,
    studentRankOfFaculty: studentRankOf[s][f] + 1
  }));
  const avg = (arr) =&gt; arr.reduce((a, b) =&gt; a + b, 0) / arr.length;
  return {
    pairs,
    avgFacultyRank: avg(pairs.map((p) =&gt; p.facultyRankOfStudent)),
    avgStudentRank: avg(pairs.map((p) =&gt; p.studentRankOfFaculty)),
    firstChoiceFaculty: pairs.filter((p) =&gt; p.facultyRankOfStudent === 1).length,
    firstChoiceStudents: pairs.filter((p) =&gt; p.studentRankOfFaculty === 1).length
  };
}







bipartiteDiagram = {
  const width = 760;
  const rowH = 34;
  const height = n * rowH + 40;
  const leftX = 170;
  const rightX = width - 170;
  const topPad = 20;
  const pairs = matching.pairs;

  const svg = d3.create("svg")
    .attr("width", width)
    .attr("height", height)
    .style("font", "13px system-ui, sans-serif");

  // Column headers
  svg.append("text")
    .attr("x", leftX).attr("y", 14)
    .attr("text-anchor", "end")
    .attr("font-weight", 600)
    .text("Faculty");
  svg.append("text")
    .attr("x", rightX).attr("y", 14)
    .attr("text-anchor", "start")
    .attr("font-weight", 600)
    .text("Student");

  // Nodes
  for (let i = 0; i &lt; n; i++) {
    const y = topPad + i * rowH + rowH / 2;
    svg.append("circle").attr("cx", leftX).attr("cy", y).attr("r", 5).attr("fill", "#1e40af");
    svg.append("text").attr("x", leftX - 10).attr("y", y + 4)
      .attr("text-anchor", "end").text(`F${i + 1}`);
    svg.append("circle").attr("cx", rightX).attr("cy", y).attr("r", 5).attr("fill", "#166534");
    svg.append("text").attr("x", rightX + 10).attr("y", y + 4)
      .attr("text-anchor", "start").text(`S${i + 1}`);
  }

  // Color by average rank across both sides (1 = both got top choice → green; n = both worst → red).
  const edgeColor = (p) =&gt; {
    const avgRank = (p.facultyRankOfStudent + p.studentRankOfFaculty) / 2;
    const t = (avgRank - 1) / (n - 1);
    return d3.interpolateRdYlGn(1 - t);
  };

  pairs.forEach((p) =&gt; {
    const y1 = topPad + p.faculty * rowH + rowH / 2;
    const y2 = topPad + p.student * rowH + rowH / 2;
    svg.append("line")
      .attr("x1", leftX + 6).attr("y1", y1)
      .attr("x2", rightX - 6).attr("y2", y2)
      .attr("stroke", edgeColor(p))
      .attr("stroke-width", 2);
  });

  return svg.node();
}







statsPanel = htl.html`&lt;div class="stats"&gt;
  &lt;div&gt;&lt;span class="stat-label"&gt;Avg rank of match (Faculty):&lt;/span&gt; &lt;span class="stat-value"&gt;${matching.avgFacultyRank.toFixed(2)}&lt;/span&gt;&lt;/div&gt;
  &lt;div&gt;&lt;span class="stat-label"&gt;Avg rank of match (Students):&lt;/span&gt; &lt;span class="stat-value"&gt;${matching.avgStudentRank.toFixed(2)}&lt;/span&gt;&lt;/div&gt;
  &lt;div&gt;&lt;span class="stat-label"&gt;Faculty who got their 1st choice:&lt;/span&gt; &lt;span class="stat-value"&gt;${matching.firstChoiceFaculty} / ${n}&lt;/span&gt;&lt;/div&gt;
  &lt;div&gt;&lt;span class="stat-label"&gt;Students who got their 1st choice:&lt;/span&gt; &lt;span class="stat-value"&gt;${matching.firstChoiceStudents} / ${n}&lt;/span&gt;&lt;/div&gt;
&lt;/div&gt;`







matchTable = {
  const rows = matching.pairs
    .slice()
    .sort((a, b) =&gt; a.faculty - b.faculty)
    .map((p) =&gt; htl.html`&lt;tr&gt;
      &lt;td&gt;F${p.faculty + 1}&lt;/td&gt;
      &lt;td&gt;S${p.student + 1}&lt;/td&gt;
      &lt;td&gt;${p.facultyRankOfStudent}&lt;/td&gt;
      &lt;td&gt;${p.studentRankOfFaculty}&lt;/td&gt;
    &lt;/tr&gt;`);
  return htl.html`&lt;table class="match-table"&gt;
    &lt;thead&gt;
      &lt;tr&gt;&lt;th&gt;Faculty&lt;/th&gt;&lt;th&gt;Matched student&lt;/th&gt;&lt;th&gt;Faculty's rank of student&lt;/th&gt;&lt;th&gt;Student's rank of faculty&lt;/th&gt;&lt;/tr&gt;
    &lt;/thead&gt;
    &lt;tbody&gt;${rows}&lt;/tbody&gt;
  &lt;/table&gt;`;
}
